/**
 * Shapes shared by the browser and the server for the two secrets of the access
 * flows. The database is the authority (it hashes, checks expiry, single use and
 * e-mail binding); these helpers only normalise input and describe states.
 *
 * - Activation codes: `LVL-XXXX-XXXX-XXXX`, 12 Crockford base32 characters
 *   (no I, L, O, U) = 60 random bits, generated by the database.
 * - Invitation links: `/auth/accept-invite?token=…`, 32 random bytes base64url.
 */

export const CROCKFORD_ALPHABET = '0123456789ABCDEFGHJKMNPQRSTVWXYZ';
export const ACTIVATION_CODE_LENGTH = 12;
/** log2(32) × 12 */
export const ACTIVATION_CODE_BITS = Math.log2(CROCKFORD_ALPHABET.length) * ACTIVATION_CODE_LENGTH;

const CODE_BODY = /^[0-9A-HJKMNP-TV-Z]{12}$/;
export const ACTIVATION_CODE_PATTERN =
  /^LVL-[0-9A-HJKMNP-TV-Z]{4}-[0-9A-HJKMNP-TV-Z]{4}-[0-9A-HJKMNP-TV-Z]{4}$/;

/**
 * What a person typed, as the 12 characters the database hashes: upper case,
 * spaces/dashes/underscores removed, `LVL` prefix dropped, Crockford decoding
 * (O reads 0, I and L read 1). Null when it cannot be a code.
 * Mirrors private.normalize_activation_code.
 */
export function normalizeActivationCode(input: string | null | undefined): string | null {
  if (!input) return null;
  let v = input
    .slice(0, 64)
    .toUpperCase()
    .replace(/[\s_-]+/g, '');
  if (v.length === 15 && v.startsWith('LVL')) v = v.slice(3);
  v = v.replace(/O/g, '0').replace(/[IL]/g, '1');
  return CODE_BODY.test(v) ? v : null;
}

/** `LVL-XXXX-XXXX-XXXX` for display (input must already be normalised). */
export function formatActivationCode(body: string): string {
  return `LVL-${body.slice(0, 4)}-${body.slice(4, 8)}-${body.slice(8, 12)}`;
}

export type CodeStatus = 'active' | 'used' | 'revoked' | 'expired';

/** Same order as private.activation_code_status. */
export function activationCodeStatus(
  code: { usedAt: string | null; revokedAt: string | null; expiresAt: string },
  now: Date = new Date()
): CodeStatus {
  if (code.usedAt) return 'used';
  if (code.revokedAt) return 'revoked';
  return new Date(code.expiresAt).getTime() <= now.getTime() ? 'expired' : 'active';
}

// ------------------------------------------------------------- invitation links

export const INVITE_TOKEN_PATTERN = /^[A-Za-z0-9_-]{43}$/;
export const INVITE_TTL_DAYS = 7;

export function isInviteToken(value: string | null | undefined): value is string {
  return !!value && INVITE_TOKEN_PATTERN.test(value);
}

export type InvitationState = 'valid' | 'accepted' | 'revoked' | 'used' | 'expired';

/** Same order as private.invitation_link_status. */
export function invitationState(
  inv: {
    acceptedAt: string | null;
    revokedAt: string | null;
    usedAt?: string | null;
    expiresAt: string;
  },
  now: Date = new Date()
): InvitationState {
  if (inv.acceptedAt) return 'accepted';
  if (inv.revokedAt) return 'revoked';
  if (inv.usedAt) return 'used';
  return new Date(inv.expiresAt).getTime() <= now.getTime() ? 'expired' : 'valid';
}

/** What the accept page may show about an invitation link (get_organization_invitation). */
export type InvitationPreview =
  | { status: 'invalid' | 'revoked' | 'used' }
  | {
      status: 'valid' | 'expired' | 'accepted';
      organization_name: string;
      website_name: string | null;
      email: string;
      role: 'owner' | 'admin' | 'editor' | 'viewer';
      inviter_name: string;
      expires_at: string;
    };

/** Invitations go to one address: case and surrounding spaces do not matter, nothing else does. */
export function emailsMatch(a: string | null | undefined, b: string | null | undefined): boolean {
  if (!a || !b) return false;
  return a.trim().toLowerCase() === b.trim().toLowerCase();
}

/** The invitation token carried by a `next` path (`/auth/accept-invite?token=…`), if any. */
export function inviteTokenFromNext(next: string | null | undefined): string | null {
  if (!next || !next.startsWith('/auth/accept-invite')) return null;
  try {
    const token = new URL(next, 'https://next.invalid').searchParams.get('token');
    return isInviteToken(token) ? token : null;
  } catch {
    return null;
  }
}

/** Destinations that finish an access flow (skip the access request form). */
export function isAccessFlowPath(path: string): boolean {
  return path.startsWith('/auth/accept-invite') || path.startsWith('/auth/activate');
}
